SELECT id, symbol, side, execution_reason, signal_id, price_usdt, decision_price_usdt, executed_at, execution_price_observed_at, TIMESTAMPDIFF(MICROSECOND, execution_price_observed_at, executed_at) / 1000000 AS price_age_s FROM crypto_ai.wallet_trade WHERE (symbol = 'EGLDUSDT' AND executed_at BETWEEN '2026-10-11 20:50:00' AND '2026-10-11 22:50:00') OR (symbol = 'XRPUSDT' AND executed_at BETWEEN '2026-10-12 02:30:00' AND '2026-10-12 03:40:00') OR (symbol = 'DOGEUSDT' AND executed_at BETWEEN '2026-10-12 04:00:00' AND '2026-10-12 04:30:00') OR (symbol = 'SHIBUSDT' AND executed_at BETWEEN '2026-10-12 06:30:00' AND '2026-10-12 07:20:00') OR (symbol = 'ACEUSDT' AND executed_at BETWEEN '2026-10-12 09:50:00' AND '2026-10-12 10:10:00') ORDER BY executed_at;